// Palette and small LVGL helpers shared by every screen.
#pragma once

#include <math.h>
#include <stdio.h>
#include <string.h>
#include "lvgl.h"

// Generated by tools/fonts.mjs: Montserrat, digits all one width.
LV_FONT_DECLARE(font_speed_150);   // - . 0-9
LV_FONT_DECLARE(font_rpm_84);      // - . 0-9
LV_FONT_DECLARE(font_value_46);    // - . 0-9
LV_FONT_DECLARE(font_text_18);     // ASCII, degree sign, middle dot

// Every colour means one thing: white is a reading, grey is a label, and the
// rest are states. Nothing is decoration.
#define C_FACE       0x000000   // background: true black, best contrast on the panel
#define C_WHITE      0xF2F4F7   // readings
#define C_MUTED      0x8A9099   // captions and units
#define C_DIM        0x5A6069   // secondary values (last drive)
#define C_TILE_LINE  0x23272E   // hairlines between sections
#define C_TILE_BG    0x101317   // buttons and dialogs
#define C_GEAR_ON_BG 0x1C2026   // pressed button
#define C_SEG_OFF    0x15181C   // an unlit tach segment

// States.
#define C_GREEN      0x3DDC84   // tach below the warning band
#define C_AMBER      0xFFB020   // caution: tach nearing shift, a reading past warn
#define C_RED        0xFF3B30   // alarm, and the tach at shift
#define C_BLUE       0x4DA3FF   // cold: not up to temperature yet

static inline lv_obj_t *ui_label(lv_obj_t *p, const char *txt, const lv_font_t *f,
                                 uint32_t color)
{
    lv_obj_t *l = lv_label_create(p);
    lv_label_set_text(l, txt);
    lv_obj_set_style_text_font(l, f, 0);
    lv_obj_set_style_text_color(l, lv_color_hex(color), 0);
    return l;
}

// Only touch LVGL when the text actually changes -- setting identical text
// still invalidates the area and costs a redraw, which on the S3 is the frame
// budget.
static inline void ui_set_text_if(lv_obj_t *l, const char *txt)
{
    if (strcmp(lv_label_get_text(l), txt) != 0)
        lv_label_set_text(l, txt);
}

static inline void ui_set_num(lv_obj_t *l, float v, const char *fmt)
{
    char b[16];
    if (isnan(v)) snprintf(b, sizeof b, "--");
    else          snprintf(b, sizeof b, fmt, v);
    ui_set_text_if(l, b);
}

// A plain black screen, not scrollable, so a horizontal drag anywhere on it
// is a swipe rather than a scroll.
static inline lv_obj_t *ui_screen(void)
{
    lv_obj_t *s = lv_obj_create(NULL);
    lv_obj_set_style_bg_color(s, lv_color_hex(C_FACE), 0);
    lv_obj_set_style_bg_opa(s, LV_OPA_COVER, 0);
    lv_obj_clear_flag(s, LV_OBJ_FLAG_SCROLLABLE);
    return s;
}

// Flat themed button: dark tile, light outline, caption centred.
static inline lv_obj_t *ui_button(lv_obj_t *p, const char *txt, int x, int y,
                                  int w, int h, uint32_t line)
{
    lv_obj_t *b = lv_btn_create(p);
    lv_obj_remove_style_all(b);
    lv_obj_set_pos(b, x, y);
    lv_obj_set_size(b, w, h);
    lv_obj_set_style_radius(b, 10, 0);
    lv_obj_set_style_bg_color(b, lv_color_hex(C_TILE_BG), 0);
    lv_obj_set_style_bg_color(b, lv_color_hex(C_GEAR_ON_BG), LV_STATE_PRESSED);
    lv_obj_set_style_bg_opa(b, LV_OPA_COVER, 0);
    lv_obj_set_style_border_color(b, lv_color_hex(line), 0);
    lv_obj_set_style_border_width(b, 2, 0);
    lv_obj_t *l = ui_label(b, txt, &lv_font_montserrat_20, C_WHITE);
    lv_obj_center(l);
    return b;
}
